CREATE TABLE public.trip_adult_activities (trip_id uuid NOT NULL, day_date date NOT NULL, kind text NOT NULL CHECK(kind IN ('bingo','quest','trivia')), item_index integer NOT NULL, prompt text NOT NULL, alternative text NOT NULL, options jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(trip_id,day_date,kind), FOREIGN KEY(trip_id,day_date) REFERENCES public.trip_day_games(trip_id,day_date) ON DELETE CASCADE);
GRANT SELECT ON public.trip_adult_activities TO authenticated; GRANT ALL ON public.trip_adult_activities TO service_role;
ALTER TABLE public.trip_adult_activities ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Only approved adults see sip or skip" ON public.trip_adult_activities FOR SELECT TO authenticated USING (trip_private.is_approved_adult(trip_id,auth.uid()));
CREATE TRIGGER trip_adult_activities_updated BEFORE UPDATE ON public.trip_adult_activities FOR EACH ROW EXECUTE FUNCTION public.set_trip_updated_at();
CREATE OR REPLACE FUNCTION trip_private.seed_adult_activities() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $fn$ BEGIN IF NEW.tag<>'Travel' THEN INSERT INTO public.trip_adult_activities(trip_id,day_date,kind,item_index,prompt,alternative) VALUES(NEW.trip_id,NEW.day_date,'bingo',0,'Sip or skip: find a local drink in '||left(NEW.city,80)||' and share a toast with your squad (any drink counts).','Find a local soda, mocktail, tea, or street-food snack and share it with your squad.') ON CONFLICT(trip_id,day_date,kind) DO UPDATE SET prompt=excluded.prompt,alternative=excluded.alternative; END IF; IF NEW.tag IN ('Explore','Party') THEN INSERT INTO public.trip_adult_activities(trip_id,day_date,kind,item_index,prompt,alternative) VALUES(NEW.trip_id,NEW.day_date,'quest',0,'Sip or skip: discover a local beverage and take a squad photo with it (any drink counts).','Discover a local nonalcoholic drink or street-food snack and take a squad photo with it.') ON CONFLICT(trip_id,day_date,kind) DO UPDATE SET prompt=excluded.prompt,alternative=excluded.alternative; END IF; IF NEW.tag='Chill' THEN INSERT INTO public.trip_adult_activities(trip_id,day_date,kind,item_index,prompt,alternative,options) VALUES(NEW.trip_id,NEW.day_date,'trivia',0,'Sip or skip: which of these is always a nonalcoholic choice?','Which drink can everyone enjoy without alcohol?', '["Beer","Sparkling water","Wine","Cocktail"]'::jsonb) ON CONFLICT(trip_id,day_date,kind) DO UPDATE SET prompt=excluded.prompt,alternative=excluded.alternative,options=excluded.options; END IF; RETURN NEW; END $fn$;
REVOKE ALL ON FUNCTION trip_private.seed_adult_activities() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER seed_adult_activities AFTER INSERT OR UPDATE ON public.trip_day_games FOR EACH ROW EXECUTE FUNCTION trip_private.seed_adult_activities();
INSERT INTO public.trip_adult_activities(trip_id,day_date,kind,item_index,prompt,alternative) SELECT trip_id,day_date,'bingo',0,'Sip or skip: find a local drink in '||left(city,80)||' and share a toast with your squad (any drink counts).','Find a local soda, mocktail, tea, or street-food snack and share it with your squad.' FROM public.trip_day_games WHERE tag<>'Travel' ON CONFLICT DO NOTHING;
INSERT INTO public.trip_adult_activities(trip_id,day_date,kind,item_index,prompt,alternative) SELECT trip_id,day_date,'quest',0,'Sip or skip: discover a local beverage and take a squad photo with it (any drink counts).','Discover a local nonalcoholic drink or street-food snack and take a squad photo with it.' FROM public.trip_day_games WHERE tag IN ('Explore','Party') ON CONFLICT DO NOTHING;
INSERT INTO public.trip_adult_activities(trip_id,day_date,kind,item_index,prompt,alternative,options) SELECT trip_id,day_date,'trivia',0,'Sip or skip: which of these is always a nonalcoholic choice?','Which drink can everyone enjoy without alcohol?','["Beer","Sparkling water","Wine","Cocktail"]'::jsonb FROM public.trip_day_games WHERE tag='Chill' ON CONFLICT DO NOTHING;
CREATE OR REPLACE FUNCTION trip_private.answer_trivia(p_trip uuid,p_date date,p_question integer,p_choice integer) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $fn$ DECLARE g public.trip_day_games := trip_private.play_day(p_trip,p_date); v_ok boolean; BEGIN IF g.tag<>'Chill' OR p_question NOT BETWEEN 0 AND 5 OR p_choice NOT BETWEEN 0 AND 3 THEN RAISE EXCEPTION 'No trivia today'; END IF; IF EXISTS(SELECT 1 FROM public.trivia_answers WHERE trip_id=p_trip AND day_date=p_date AND user_id=auth.uid() AND question=p_question) THEN RAISE EXCEPTION 'Already answered'; END IF; IF p_question=0 AND trip_private.is_approved_adult(p_trip,auth.uid()) AND EXISTS(SELECT 1 FROM public.trip_adult_activities WHERE trip_id=p_trip AND day_date=p_date AND kind='trivia') THEN v_ok:=p_choice=1; ELSE SELECT (answers->>p_question)::int=p_choice INTO v_ok FROM public.trip_day_trivia_keys WHERE trip_id=p_trip AND day_date=p_date; END IF; v_ok:=coalesce(v_ok,false); INSERT INTO public.trivia_answers(trip_id,day_date,user_id,question,choice,correct) VALUES(p_trip,p_date,auth.uid(),p_question,p_choice,v_ok); RETURN v_ok; END $fn$;